package com.restaurantmanagement.controller; import com.restaurantmanagement.entity.Restaurant; import com.restaurantmanagement.repository.RestaurantRepository; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/restaurants") public class RestaurantController {private final RestaurantRepository repo;public RestaurantController(RestaurantRepository r){repo=r;} @GetMapping public List<Restaurant> list(){return repo.findAll();} }
